input.command:
set -e
npm install astro @ascribed/astro sharp 2>&1 | tail -4
npm ls astro @ascribed/astro @ascribed/cli --depth=0
cat > astro.config.mjs <<'EOF'
import { defineConfig } from "astro/config";
import ascribe from "@ascribed/astro";

// `site` repeats ascribe.toml's [consumer]; the integration fails the build
// if they disagree.
export default defineConfig({
  site: "http://localhost:4321",
  integrations: [ascribe({ build: "site" })],
});
EOF
cat > src/content.config.ts <<'EOF'
import { defineCollection } from "astro:content";
import { ascribeCollection } from "@ascribed/astro/content";
// Generated by `ascribe build --emit site`; the integration runs it first.
import { schema } from "../.ascribe/build/site/site/_ascribe/schema.ts";

export const collections = {
  docs: defineCollection(ascribeCollection({ schema })),
};
EOF
cat > 'src/pages/[...slug].astro' <<'EOF'
---
import { getCollection, render } from "astro:content";
import Docs from "../layouts/Docs.astro";

// A page's route is the base path plus its entry id, and the root page (id
// `index`) is at the base path itself: what Ascribe's router computes for
// every link it writes.
export async function getStaticPaths() {
  const entries = await getCollection("docs");
  return entries.map((entry) => ({
    params: { slug: entry.id === "index" ? undefined : entry.id },
    props: { entry },
  }));
}

const { entry } = Astro.props;
const { Content, headings } = await render(entry);
---

<Docs entry={entry} headings={headings}><Content /></Docs>
EOF
cat > src/layouts/Docs.astro <<'EOF'
---
import type { CollectionEntry } from "astro:content";
import Availability from "@ascribed/astro/Availability.astro";
import Elements from "@ascribed/astro/Elements.astro";

interface Props {
  entry: CollectionEntry<"docs">;
  headings: { depth: number; slug: string; text: string }[];
}

const { entry, headings } = Astro.props;
const { title, description, available } = entry.data;
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{title}</title>
    <Elements />
    {description && <meta name="description" content={description} />}
  </head>
  <body>
    <main>
      <h1>{title}</h1>
      <Availability available={available} />
      <nav aria-label="On this page">
        <ul>
          {
            headings.map((heading) => (
              <li data-depth={heading.depth}>
                <a href={`#${heading.slug}`}>{heading.text}</a>
              </li>
            ))
          }
        </ul>
      </nav>
      <article><slot /></article>
    </main>
  </body>
</html>

<style is:global>
  body {
    margin: 0;
    font-family: system-ui, sans-serif;
    line-height: 1.6;
    color: #1f2328;
    background: #fff;
  }
  main {
    max-width: 42rem;
    margin: 0 auto;
    padding: 2rem 1rem 4rem;
  }
</style>
EOF
npm pkg set type=module scripts.dev="astro dev" scripts.build="astro build" scripts.preview="astro preview" scripts.check="ascribe check" >/dev/null
npm pkg delete scripts.test main >/dev/null
npx astro build 2>&1 | tail -25

